/**
 * One-shot cleanup: delete the FUTURE Happy Valley H3 (hvh3) placeholder
 * events generated by the now-disabled "Happy Valley H3 Static Schedule".
 *
 * Background: the static source's "biweekly Thursday 6:30 PM" rule had no
 * recorded provenance (the kennel's site, last edited 2023-05-02, listed
 * ~monthly weekend-afternoon trails; the only live channel is a private
 * Facebook group), and without an anchorDate it flip-flopped its parity every
 * scrape. Migration 20261105130000_disable_hvh3_static_schedule disables the
 * source; this script removes the synthetic future events it already created,
 * so the kennel page stops listing Thursdays that aren't real. Past events are
 * left alone (out of scope; they carry no attendance and are history-only).
 *
 * Selection (intentionally narrow):
 *   - kennel `hvh3`, Event.date >= today (UTC)
 *   - EVERY RawEvent on the event comes from the HVH3 static source (an event
 *     with any other source's RawEvent is real data and is skipped)
 *   - no Attendance / KennelAttendance rows (a check-in on a synthetic
 *     placeholder is unexpected — skipped and reported loudly)
 *
 * Mirrors scripts/cleanup-dcfmh3-placeholder-events.ts: dry run by default,
 * deletes the placeholders' RawEvents + Events in one transaction on apply
 * (EventKennel / EventLink cascade on Event delete).
 *
 * Usage (after the migration has deployed):
 *   Dry run:  npx tsx scripts/cleanup-hvh3-static-placeholders.ts
 *   Apply:    CLEANUP_APPLY=1 npx tsx scripts/cleanup-hvh3-static-placeholders.ts
 */

import "dotenv/config";
import { prisma } from "@/lib/db";

const KENNEL_CODE = "hvh3";
const SOURCE_NAME = "Happy Valley H3 Static Schedule";
const APPLY = process.env.CLEANUP_APPLY === "1";
// Prisma's interactive-transaction default is 5s; a bulk delete over a no-eventId-index
// RawEvent table takes far longer (the Oregon apply on 2026-11-05 died at 76s with P2028
// and rolled back). Give the one-shot room.
const BULK_TX_OPTIONS = { timeout: 600_000, maxWait: 60_000 };

interface Candidate {
  id: string;
  date: Date;
  status: string;
  rawSourceIds: string[];
  attendances: number;
}

/**
 * Pure selection: which candidate events are safe to delete. Exported for tests.
 * An event qualifies only if it has ≥1 RawEvent, all from the static source,
 * and no attendance of either kind.
 */
export function partitionPlaceholders(candidates: Candidate[], staticSourceId: string) {
  const deletable: Candidate[] = [];
  const otherSource: Candidate[] = [];
  const withAttendance: Candidate[] = [];
  for (const c of candidates) {
    const onlyStatic = c.rawSourceIds.length > 0 && c.rawSourceIds.every((id) => id === staticSourceId);
    if (!onlyStatic) otherSource.push(c);
    else if (c.attendances > 0) withAttendance.push(c);
    else deletable.push(c);
  }
  return { deletable, otherSource, withAttendance };
}

async function main() {
  const kennel = await prisma.kennel.findFirst({ where: { kennelCode: KENNEL_CODE }, select: { id: true } });
  if (!kennel) throw new Error(`Kennel ${KENNEL_CODE} not found`);
  const source = await prisma.source.findFirst({
    where: { name: SOURCE_NAME, type: "STATIC_SCHEDULE" },
    select: { id: true, enabled: true },
  });
  if (!source) throw new Error(`Source "${SOURCE_NAME}" not found`);
  if (source.enabled) {
    throw new Error(
      `Source "${SOURCE_NAME}" is still enabled — deploy migration 20261105130000_disable_hvh3_static_schedule first, ` +
        `or the next scrape will regenerate everything this script deletes.`,
    );
  }

  const today = new Date();
  today.setUTCHours(0, 0, 0, 0);
  const events = await prisma.event.findMany({
    where: { kennelId: kennel.id, date: { gte: today } },
    select: {
      id: true,
      date: true,
      status: true,
      rawEvents: { select: { sourceId: true } },
      _count: { select: { attendances: true, kennelAttendances: true } },
    },
    orderBy: { date: "asc" },
  });

  const candidates: Candidate[] = events.map((e) => ({
    id: e.id,
    date: e.date,
    status: e.status,
    rawSourceIds: e.rawEvents.map((r) => r.sourceId),
    attendances: e._count.attendances + e._count.kennelAttendances,
  }));
  const { deletable, otherSource, withAttendance } = partitionPlaceholders(candidates, source.id);

  console.log(`Future ${KENNEL_CODE} events: ${candidates.length}`);
  for (const c of candidates) {
    const tag = deletable.includes(c)
      ? "DELETE"
      : withAttendance.includes(c)
        ? "SKIP (has attendance)"
        : "KEEP (other source)";
    console.log(`  ${c.date.toISOString().slice(0, 10)}  status=${c.status}  raws=${c.rawSourceIds.length}  ${tag}`);
  }
  if (withAttendance.length > 0) {
    console.warn(`\n⚠️  ${withAttendance.length} placeholder(s) have attendance and were NOT selected — investigate.`);
  }
  if (otherSource.length > 0) {
    console.log(`\n${otherSource.length} future event(s) are backed by another source and are kept.`);
  }

  if (!APPLY) {
    console.log(`\nDry run. Would delete ${deletable.length} placeholder event(s) (+ their RawEvents).`);
    console.log("Re-run with CLEANUP_APPLY=1 to apply.");
    return;
  }

  const ids = deletable.map((c) => c.id);
  const result = await prisma.$transaction(async (tx) => {
    const raws = await tx.rawEvent.deleteMany({ where: { eventId: { in: ids }, sourceId: source.id } });
    const deleted = await tx.event.deleteMany({ where: { id: { in: ids } } });
    return { raws: raws.count, events: deleted.count };
  }, BULK_TX_OPTIONS);
  console.log(`\n✅ Deleted ${result.events} placeholder events and ${result.raws} static-schedule RawEvents.`);
}

if (process.argv[1]?.endsWith("cleanup-hvh3-static-placeholders.ts")) {
  main()
    .catch((err) => {
      console.error(err);
      process.exitCode = 1;
    })
    .finally(() => prisma.$disconnect());
}
